1	import type Phaser from 'phaser';
2	import { Difficulty, Difficulty as DifficultyEnum } from '../types/GameMode';
3	import {
4	  getLeaderboard,
5	  claimSeasonReward,
6	  claimCharacterReward,
7	  getCachedClaimAmount,
8	  getCachedCharClaimAmount,
9	  type LeaderboardEntry,
10	  type PrevSeasonReward,
11	} from '../utils/leaderboard';
12	import { CHARACTERS } from '../utils/character';
13	import BaseScene from './BaseScene';
14	
15	export default class LeaderboardScene extends BaseScene {
16	  private selectedDifficulty: Difficulty = DifficultyEnum.NORMAL;
17	  private leaderboardData: LeaderboardEntry[] = [];
18	  private leaderboardTexts: Phaser.GameObjects.GameObject[] = [];
19	  private loadingText?: Phaser.GameObjects.Text;
20	  private errorText?: Phaser.GameObjects.Text;
21	  private currentRequestId: number = 0;
22	  private difficultyButtons = new Map<Difficulty, Phaser.GameObjects.Rectangle>();
23	
24	  // EXTREME 캐릭터 필터
25	  private selectedCharFilter: string | null = null;
26	  private charFilterObjects: Phaser.GameObjects.GameObject[] = [];
27	  private charOverlayObjects: Phaser.GameObjects.GameObject[] = [];
28	  private overlayCleanup?: () => void;
29	
30	  // 시즌 UI 요소
31	  private seasonText?: Phaser.GameObjects.Text;
32	  private prevSeasonReward: PrevSeasonReward | null = null;
33	
34	  // 보상수령 버튼 (create에서 1회 생성, updateRewardUI에서 상태 변경)
35	  private rewardBtnBg?: Phaser.GameObjects.Rectangle;
36	  private rewardBtnLabel?: Phaser.GameObjects.Text;
37	
38	  constructor() {
39	    super('LeaderboardScene');
40	  }
41	
42	  init() {
43	    const last = localStorage.getItem('lastPlayedDifficulty') as Difficulty | null;
44	    if (last) {
45	      this.selectedDifficulty = last;
46	    }
47	  }
48	
49	  preload() {
50	    if (!this.textures.exists('background2')) {
51	      this.load.image('background2', 'assets/backgrounds/background2.webp');
52	    }
53	    // 캐릭터 아이콘 (랭킹 표시용) + 일러스트 (캐릭터 선택 오버레이용)
54	    CHARACTERS.forEach(char => {
55	      if (!this.textures.exists(char.imageKey)) {
56	        this.load.image(char.imageKey, char.imagePath);
57	      }
58	      if (!this.textures.exists(char.illustKey)) {
59	        this.load.image(char.illustKey, char.illustPath);
60	      }
61	    });
62	  }
63	
64	  create() {
65	    super.create();
66	
67	    this.events.once('shutdown', () => this.overlayCleanup?.());
68	
69	    const W = this.scale.width;
70	    const H = this.scale.height;
71	    const cx = W / 2;
72	    const yOff = (H - 600) / 2;
73	
74	    // 배경 이미지 추가
75	    const background = this.add.image(cx, H / 2, 'background2');
76	    background.setDisplaySize(W, H);
77	
78	    // 타이틀
79	    this.add.text(cx, 40 + yOff, '🏆 랭킹보드 🏆', {
80	      fontSize: '28px',
81	      color: '#fff',
82	      fontStyle: 'bold',
83	      stroke: '#000',
84	      strokeThickness: 5,
85	      padding: { top: 6 },
86	    }).setOrigin(0.5);
87	
88	    // 시즌 월 표시 (데이터 로드 후 갱신)
89	    this.seasonText = this.add.text(cx, 70 + yOff, '', {
90	      fontSize: '13px',
91	      color: '#aaddff',
92	      stroke: '#000',
93	      strokeThickness: 3,
94	    }).setOrigin(0.5);
95	
96	    // 난이도 선택 버튼들
97	    this.createDifficultyButtons(cx, yOff);
98	
99	    // 랭킹 표시 영역 (초기 로딩)
100	    this.loadingText = this.add.text(cx, H / 2, '로딩 중...', {
101	      fontSize: '20px',
102	      color: '#fff',
103	      stroke: '#000',
104	      strokeThickness: 3
105	    }).setOrigin(0.5);
106	
107	    // 보상수령 버튼 (하단 왼쪽, 뒤로가기와 나란히)
108	    const rbY = H - 40;
109	    this.rewardBtnBg = this.add.rectangle(cx - 80, rbY, 150, 40, 0x555555, 1);
110	    this.rewardBtnBg.setStrokeStyle(3, 0x333333);
111	    this.rewardBtnLabel = this.add.text(cx - 80, rbY, '보상수령', {
112	      fontSize: '18px',
113	      color: '#999999',
114	      fontStyle: 'bold',
115	      stroke: '#000',
116	      strokeThickness: 4,
117	    }).setOrigin(0.5);
118	
119	    // 뒤로가기 버튼 (하단 오른쪽)
120	    this.createBackButton(cx + 80, H - 40);
121	
122	    // 초기 데이터 로드
123	    this.loadLeaderboard();
124	  }
125	
126	  private createDifficultyButtons(cx: number, yOff: number) {
127	    this.difficultyButtons.forEach(btn => btn.destroy());
128	    this.difficultyButtons.clear();
129	
130	    const difficulties: Difficulty[] = [
131	      DifficultyEnum.NORMAL,
132	      DifficultyEnum.HARD,
133	      DifficultyEnum.EXTREME,
134	      DifficultyEnum.PHYSICAL
135	    ];
136	
137	    const buttonWidth = 70;
138	    const spacing = 85;
139	    const startX = cx - (spacing * 1.5);
140	    const y = 108 + yOff;
141	
142	    difficulties.forEach((difficulty, index) => {
143	      const x = startX + (index * spacing);
144	      const isSelected = difficulty === this.selectedDifficulty;
145	
146	      const button = this.add.rectangle(
147	        x,
148	        y,
149	        buttonWidth,
150	        35,
151	        isSelected ? 0xffff99 : 0xffffff,
152	        1
153	      );
154	      button.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
155	
156	      this.add.text(x, y, difficulty, {
157	        fontSize: '12px',
158	        color: '#000',
159	        fontStyle: 'bold'
160	      }).setOrigin(0.5);
161	
162	      this.difficultyButtons.set(difficulty, button);
163	      button.setInteractive({ useHandCursor: true });
164	
165	      button.on('pointerover', () => {
166	        if (difficulty !== this.selectedDifficulty) {
167	          button.setFillStyle(0xffffcc);
168	        }
169	      });
170	
171	      button.on('pointerout', () => {
172	        if (difficulty !== this.selectedDifficulty) {
173	          button.setFillStyle(0xffffff);
174	        }
175	      });
176	
177	      button.on('pointerdown', () => {
178	        this.selectDifficulty(difficulty);
179	      });
180	    });
181	  }
182	
183	  private selectDifficulty(difficulty: Difficulty) {
184	    if (this.selectedDifficulty === difficulty) return;
185	
186	    this.selectedDifficulty = difficulty;
187	
188	    // 난이도 전환 시 캐릭터 필터 초기화
189	    this.selectedCharFilter = null;
190	    this.charFilterObjects.forEach(o => o.destroy());
191	    this.charFilterObjects = [];
192	
193	    this.difficultyButtons.forEach((btn, diff) => {
194	      const isSelected = diff === difficulty;
195	      btn.setFillStyle(isSelected ? 0xffff99 : 0xffffff);
196	      btn.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
197	    });
198	
199	    this.loadLeaderboard();
200	  }
201	
202	  private async loadLeaderboard() {
203	    // 요청 ID 증가 (새로운 요청 시작)
204	    this.currentRequestId++;
205	    const requestId = this.currentRequestId;
206	
207	    // 기존 랭킹 텍스트 제거
208	    this.leaderboardTexts.forEach(text => text.destroy());
209	    this.leaderboardTexts = [];
210	    this.prevSeasonReward = null;
211	
212	    if (this.errorText) {
213	      this.errorText.destroy();
214	      this.errorText = undefined;
215	    }
216	
217	    // 로딩 표시
218	    if (!this.loadingText) {
219	      this.loadingText = this.add.text(this.scale.width / 2, this.scale.height / 2, '로딩 중...', {
220	        fontSize: '20px',
221	        color: '#fff',
222	        stroke: '#000',
223	        strokeThickness: 3
224	      }).setOrigin(0.5);
225	    } else {
226	      this.loadingText.setVisible(true);
227	    }
228	
229	    try {
230	      const response = await getLeaderboard(
231	        this.selectedDifficulty,
232	        10,
233	        this.selectedCharFilter ?? undefined
234	      );
235	
236	      if (requestId !== this.currentRequestId) return;
237	
238	      this.leaderboardData = response.leaderboard;
239	
240	      // 시즌 텍스트 갱신
241	      if (this.seasonText && response.yearMonth) {
242	        const [y, m] = response.yearMonth.split('-');
243	        const daysLeft = this.calcDaysUntilMonthEnd();
244	        this.seasonText.setText(`${y}년 ${parseInt(m)}월 시즌  |  시즌 종료까지 D-${daysLeft}`);
245	      }
246	
247	      // 직전 달 보상 상태 결정 (localStorage 캐시 우선)
248	      if (response.yearMonth) {
249	        const [y, m] = response.yearMonth.split('-').map(Number) as [number, number];
250	        const prevDate = new Date(Date.UTC(y, m - 2, 1));
251	        const prevYM = `${prevDate.getUTCFullYear()}-${String(prevDate.getUTCMonth() + 1).padStart(2, '0')}`;
252	
253	        if (this.selectedCharFilter !== null) {
254	          const cached = getCachedCharClaimAmount(prevYM, this.selectedCharFilter);
255	          if (cached !== null) {
256	            this.prevSeasonReward = {
257	              yearMonth: prevYM,
258	              rank: response.prevSeasonReward?.rank ?? null,
259	              skorAwarded: cached,
260	              alreadyClaimed: true,
261	            };
262	          } else {
263	            this.prevSeasonReward = response.prevSeasonReward;
264	          }
265	        } else {
266	          const cached = getCachedClaimAmount(prevYM, this.selectedDifficulty);
267	          if (cached !== null) {
268	            this.prevSeasonReward = {
269	              yearMonth: prevYM,
270	              rank: response.prevSeasonReward?.rank ?? null,
271	              skorAwarded: cached,
272	              alreadyClaimed: true,
273	            };
274	          } else {
275	            this.prevSeasonReward = response.prevSeasonReward;
276	          }
277	        }
278	      } else {
279	        this.prevSeasonReward = null;
280	      }
281	
282	      if (this.loadingText) {
283	        this.loadingText.setVisible(false);
284	      }
285	
286	      this.displayLeaderboard();
287	      this.updateCharFilterRow();
288	      this.updateRewardUI();
289	    } catch (error) {
290	      // 에러가 발생했을 때도 최신 요청인지 확인
291	      if (requestId !== this.currentRequestId) {
292	        // 이미 새로운 요청이 시작됨 - 이 에러는 무시
293	        return;
294	      }
295	
296	      console.error('Failed to load leaderboard:', error);
297	
298	      if (this.loadingText) {
299	        this.loadingText.setVisible(false);
300	      }
301	
302	      this.errorText = this.add.text(this.scale.width / 2, this.scale.height / 2, '랭킹을 불러올 수 없습니다\n\n나중에 다시 시도해주세요', {
303	        fontSize: '16px',
304	        color: '#ff6666',
305	        stroke: '#000',
306	        strokeThickness: 3,
307	        align: 'center'
308	      }).setOrigin(0.5);
309	    }
310	  }
311	
312	  private displayLeaderboard() {
313	    const W = this.scale.width;
314	    const yOff = (this.scale.height - 600) / 2;
315	    const startY = (this.selectedDifficulty === DifficultyEnum.EXTREME ? 170 : 130) + yOff;
316	    const ROW_H = 38;
317	    const PAD = 48;
318	    const ROW_W = W - PAD * 2;
319	    const LEFT = PAD;
320	    const CX = W / 2;
321	
322	    // 컬럼 x 좌표 (모두 W 기준 비율 계산)
323	    // [순위 50px] [아이콘 44px] [← 이름 중앙 정렬 →] [점수 110px]
324	    const COL_RANK       = LEFT + 40;
325	    const COL_ICON       = LEFT + 72;
326	    const ICON_R         = LEFT + 89;
327	    const SCORE_L        = LEFT + ROW_W - 110;
328	    const COL_NAME       = (ICON_R + SCORE_L) / 2;
329	    const COL_SCORE      = LEFT + ROW_W - 6;
330	
331	    // ── 헤더 ────────────────────────────────────────────
332	    const headerY = startY + 16;
333	    const headerStyle = {
334	      fontSize: '13px',
335	      color: '#aaddff',
336	      fontStyle: 'bold',
337	      stroke: '#000',
338	      strokeThickness: 3,
339	    };
340	    this.leaderboardTexts.push(
341	      this.add.text(COL_RANK, headerY, '순위', headerStyle).setOrigin(1, 0.5),
342	      this.add.text(COL_NAME, headerY, '이름', headerStyle).setOrigin(0.5, 0.5),
343	      this.add.text(COL_SCORE, headerY, '점수', headerStyle).setOrigin(1, 0.5),
344	    );
345	    const divider = this.add.rectangle(CX, headerY + 11, ROW_W, 1, 0xaaddff, 0.5);
346	    this.leaderboardTexts.push(divider);
347	
348	    // ── 데이터 없음 ──────────────────────────────────────
349	    if (this.leaderboardData.length === 0) {
350	      const noDataText = this.add.text(
351	        CX, startY + 80,
352	        '아직 랭킹이 없습니다\n\n첫 번째 플레이어가 되어보세요!',
353	        { fontSize: '18px', color: '#ccc', stroke: '#000', strokeThickness: 3, align: 'center' }
354	      ).setOrigin(0.5);
355	      this.leaderboardTexts.push(noDataText);
356	      return;
357	    }
358	
359	    // ── 각 행 ────────────────────────────────────────────
360	    this.leaderboardData.forEach((entry, index) => {
361	      const rowY = startY + 38 + index * ROW_H;
362	      const cy = rowY + ROW_H / 2;
363	
364	      // 행 배경
365	      const bgColor =
366	        entry.rank === 1 ? 0x4a3a00 :
367	        entry.rank === 2 ? 0x2a2a35 :
368	        entry.rank === 3 ? 0x3a2010 :
369	        index % 2 === 0  ? 0x0a0a18 : 0x121220;
370	      const bgAlpha = entry.rank <= 3 ? 0.85 : 0.55;
371	      const bg = this.add.rectangle(CX, cy, ROW_W, ROW_H - 2, bgColor, bgAlpha);
372	      this.leaderboardTexts.push(bg);
373	
374	      // 상위 3위 왼쪽 테두리 강조
375	      if (entry.rank <= 3) {
376	        const accentColor = entry.rank === 1 ? 0xFFD700 : entry.rank === 2 ? 0xC0C0C0 : 0xCD7F32;
377	        const accent = this.add.rectangle(LEFT + 1, cy, 3, ROW_H - 2, accentColor, 1);
378	        this.leaderboardTexts.push(accent);
379	      }
380	
381	      // 순위 색상
382	      const rankColor =
383	        entry.rank === 1 ? '#FFD700' :
384	        entry.rank === 2 ? '#C0C0C0' :
385	        entry.rank === 3 ? '#CD7F32' : '#aaaaaa';
386	
387	      // 순위 (숫자만)
388	      this.leaderboardTexts.push(
389	        this.add.text(COL_RANK, cy, `${entry.rank}`, {
390	          fontSize: '15px',
391	          color: rankColor,
392	          fontStyle: 'bold',
393	          stroke: '#000',
394	          strokeThickness: 3,
395	        }).setOrigin(1, 0.5)
396	      );
397	
398	      // 캐릭터 아이콘
399	      const charDef = CHARACTERS.find(c => c.id === (entry.characterType ?? 'chibi')) ?? CHARACTERS[0];
400	      this.leaderboardTexts.push(
401	        this.add.image(COL_ICON, cy, charDef.imageKey).setDisplaySize(30, 30).setOrigin(0.5)
402	      );
403	
404	      // 이름
405	      this.leaderboardTexts.push(
406	        this.add.text(COL_NAME, cy, entry.userName, {
407	          fontSize: '15px',
408	          color: entry.rank <= 3 ? '#ffffff' : '#dddddd',
409	          fontFamily: 'monospace',
410	          fontStyle: 'bold',
411	          stroke: '#000',
412	          strokeThickness: 3,
413	        }).setOrigin(0.5, 0.5)
414	      );
415	
416	      // 점수
417	      this.leaderboardTexts.push(
418	        this.add.text(COL_SCORE, cy, entry.score.toLocaleString(), {
419	          fontSize: '15px',
420	          color: entry.rank <= 3 ? rankColor : '#ffffff',
421	          fontFamily: 'monospace',
422	          fontStyle: 'bold',
423	          stroke: '#000',
424	          strokeThickness: 3,
425	        }).setOrigin(1, 0.5)
426	      );
427	    });
428	  }
429	
430	  /** EXTREME 선택 시 캐릭터 필터 드롭다운 버튼 렌더 */
431	  private updateCharFilterRow() {
432	    this.charFilterObjects.forEach(o => o.destroy());
433	    this.charFilterObjects = [];
434	
435	    if (this.selectedDifficulty !== DifficultyEnum.EXTREME) return;
436	
437	    const W = this.scale.width;
438	    const yOff = (this.scale.height - 600) / 2;
439	    const cy = 145 + yOff;
440	    const cx = W / 2;
441	
442	    const selectedName = this.selectedCharFilter === null
443	      ? '전체'
444	      : (CHARACTERS.find(c => c.id === this.selectedCharFilter)?.name ?? this.selectedCharFilter);
445	    const label = `👤 ${selectedName}  ▼`;
446	
447	    const btn = this.add.rectangle(cx, cy, 180, 28, 0x1a1a3a, 1);
448	    btn.setStrokeStyle(2, 0x5566aa);
449	    const txt = this.add.text(cx, cy, label, {
450	      fontSize: '12px', color: '#aaccff', fontStyle: 'bold',
451	    }).setOrigin(0.5);
452	
453	    btn.setInteractive({ useHandCursor: true });
454	    btn.on('pointerover', () => btn.setFillStyle(0x2a2a5a));
455	    btn.on('pointerout',  () => btn.setFillStyle(0x1a1a3a));
456	    btn.on('pointerdown', () => this.showCharSelectOverlay());
457	
458	    this.charFilterObjects.push(btn, txt);
459	  }
460	
461	  /** 캐릭터 선택 오버레이 표시 (일러스트 포트레이트 카드, 스크롤 가능) */
462	  private showCharSelectOverlay() {
463	    if (this.charOverlayObjects.length > 0) return;
464	
465	    const W = this.scale.width;
466	    const H = this.scale.height;
467	    const cx = W / 2;
468	    const yOff = (H - 600) / 2;
469	    const DEPTH = 500;
470	
471	    // 반투명 배경 (이벤트 흡수)
472	    const bg = this.add.rectangle(cx, H / 2, W, H, 0x000000, 0.92)
473	      .setDepth(DEPTH).setInteractive();
474	    this.charOverlayObjects.push(bg);
475	
476	    // 타이틀
477	    this.charOverlayObjects.push(
478	      this.add.text(cx, 38 + yOff, '캐릭터 선택', {
479	        fontSize: '20px', color: '#ffffff', fontStyle: 'bold',
480	        stroke: '#000', strokeThickness: 4,
481	      }).setOrigin(0.5).setDepth(DEPTH + 1)
482	    );
483	
484	    // 오버레이가 열린 시각을 기록해 200ms 이내 pointerup은 모두 무시한다.
485	    // (드롭다운 pointerdown → 오버레이 생성 → 같은 손가락 pointerup이 카드·버튼에 전달되는 고스트 클릭 방지)
486	    // Phaser 이벤트 순서에 의존하는 readyForInput 패턴을 대체한다.
487	    const openedAt = Date.now();
488	    const OPEN_DEBOUNCE = 200;
489	
490	    const scroll = { y: 0, startY: 0, startScrollY: 0, active: false, hasDragged: false };
491	
492	    // "전체 랭킹" 버튼
493	    const allSel = this.selectedCharFilter === null;
494	    const allBg = this.add.rectangle(cx, 68 + yOff, 160, 30,
495	      allSel ? 0x334488 : 0x222233, 1).setDepth(DEPTH + 1);
496	    allBg.setStrokeStyle(2, allSel ? 0xaaccff : 0x444466);
497	    const allTxt = this.add.text(cx, 68 + yOff, '전체 랭킹', {
498	      fontSize: '13px', color: allSel ? '#ffffff' : '#8899bb', fontStyle: 'bold',
499	    }).setOrigin(0.5).setDepth(DEPTH + 2);
500	    allBg.setInteractive({ useHandCursor: true });
501	    allBg.on('pointerup', () => {
502	      if (Date.now() - openedAt < OPEN_DEBOUNCE || scroll.hasDragged) return;
503	      this.hideCharSelectOverlay();
504	      if (this.selectedCharFilter !== null) {
505	        this.selectedCharFilter = null;
506	        this.loadLeaderboard();
507	      }
508	    });
509	    this.charOverlayObjects.push(allBg, allTxt);
510	
511	    // 닫기 버튼 (하단 고정) — 스크롤 영역 밖이므로 hasDragged 체크 불필요
512	    const closeY = H - 24;
513	    const closeBg = this.add.rectangle(cx, closeY, 100, 30, 0x333333, 1)
514	      .setDepth(DEPTH + 1).setStrokeStyle(2, 0x666666);
515	    const closeTxt = this.add.text(cx, closeY, '✕ 닫기', {
516	      fontSize: '13px', color: '#cccccc', fontStyle: 'bold',
517	    }).setOrigin(0.5).setDepth(DEPTH + 2);
518	    closeBg.setInteractive({ useHandCursor: true });
519	    closeBg.on('pointerup', () => {
520	      if (Date.now() - openedAt < OPEN_DEBOUNCE) return;
521	      this.hideCharSelectOverlay();
522	    });
523	    this.charOverlayObjects.push(closeBg, closeTxt);
524	
525	    // 스크롤 영역 정의
526	    const SCROLL_TOP = 90 + yOff;
527	    const SCROLL_BOTTOM = H - 46;
528	    const scrollAreaH = SCROLL_BOTTOM - SCROLL_TOP;
529	
530	    // 카드 크기 (4열 포트레이트)
531	    const COLS = 4;
532	    const CELL_W = 90;
533	    const CELL_H = 112;
534	    const CARD_W = 84;
535	    const CARD_H = 106;
536	    const gridLeft = (W - COLS * CELL_W) / 2; // = 20px
537	
538	    const ROWS = Math.ceil(CHARACTERS.length / COLS);
539	    const totalGridH = ROWS * CELL_H;
540	    const maxScroll = Math.max(0, totalGridH - scrollAreaH);
541	
542	    // GeometryMask — 스크롤 뷰포트 클리핑
543	    const maskGfx = this.add.graphics();
544	    maskGfx.fillStyle(0xffffff);
545	    maskGfx.fillRect(0, SCROLL_TOP, W, scrollAreaH);
546	    const mask = maskGfx.createGeometryMask();
547	    this.charOverlayObjects.push(maskGfx);
548	
549	    // 카드 컨테이너 (container.y = -scroll.y 로 스크롤)
550	    const cardContainer = this.add.container(0, 0).setDepth(DEPTH + 1);
551	    cardContainer.setMask(mask);
552	    this.charOverlayObjects.push(cardContainer);
553	
554	    const gradeColor: Record<string, number> = {
555	      '등급외': 0x888888, R: 0x4488ff, SR: 0xcc55ff, UR: 0xffcc00,
556	    };
557	
558	    CHARACTERS.forEach((char, i) => {
559	      const col = i % COLS;
560	      const row = Math.floor(i / COLS);
561	      const lx = gridLeft + col * CELL_W + CELL_W / 2;
562	      const ly = SCROLL_TOP + row * CELL_H + CELL_H / 2;
563	      const isSel = this.selectedCharFilter === char.id;
564	
565	      // 카드 배경
566	      const cardBg = this.add.rectangle(lx, ly, CARD_W, CARD_H, 0x0a0a18, 1);
567	      cardBg.setStrokeStyle(isSel ? 3 : 1, isSel ? 0xaaccff : 0x222240);
568	
569	      // 일러스트 이미지 (카드 꽉 채움)
570	      const illust = this.add.image(lx, ly, char.illustKey)
571	        .setDisplaySize(CARD_W, CARD_H).setOrigin(0.5);
572	      if (!isSel) illust.setAlpha(0.75);
573	
574	      // 하단 그라디언트 (이름 가독성)
575	      const grad = this.add.graphics();
576	      grad.fillGradientStyle(0x000000, 0x000000, 0x000000, 0x000000, 0, 0, 0.88, 0.88);
577	      grad.fillRect(lx - CARD_W / 2, ly + CARD_H / 2 - 30, CARD_W, 30);
578	
579	      // 이름 텍스트
580	      const nameTxt = this.add.text(lx, ly + CARD_H / 2 - 5, char.name, {
581	        fontSize: '9px', color: '#ffffff', fontStyle: 'bold',
582	        stroke: '#000', strokeThickness: 2,
583	      }).setOrigin(0.5, 1);
584	
585	      // 등급 뱃지 (우상단 원)
586	      const dot = this.add.circle(
587	        lx + CARD_W / 2 - 8, ly - CARD_H / 2 + 8,
588	        5, gradeColor[char.grade] ?? 0x888888, 1
589	      );
590	
591	      // 선택 시 하이라이트 오버레이
592	      if (isSel) {
593	        const sel = this.add.rectangle(lx, ly, CARD_W, CARD_H, 0x5588ff, 0.18);
594	        cardContainer.add(sel);
595	      }
596	
597	      cardContainer.add([cardBg, illust, grad, nameTxt, dot]);
598	
599	      cardBg.setInteractive({ useHandCursor: true });
600	      cardBg.on('pointerup', (ptr: Phaser.Input.Pointer) => {
601	        if (Date.now() - openedAt < OPEN_DEBOUNCE || scroll.hasDragged) return;
602	        if (ptr.y < SCROLL_TOP || ptr.y > SCROLL_BOTTOM) return;
603	        this.hideCharSelectOverlay();
604	        if (this.selectedCharFilter !== char.id) {
605	          this.selectedCharFilter = char.id;
606	          this.loadLeaderboard();
607	        }
608	      });
609	    });
610	
611	    // 씬 레벨 드래그 핸들러 (스크롤)
612	    const onDown = (ptr: Phaser.Input.Pointer) => {
613	      if (ptr.y < SCROLL_TOP || ptr.y > SCROLL_BOTTOM) return;
614	      scroll.startY = ptr.y;
615	      scroll.startScrollY = scroll.y;
616	      scroll.active = true;
617	      scroll.hasDragged = false;
618	    };
619	    const onMove = (ptr: Phaser.Input.Pointer) => {
620	      if (!scroll.active || !ptr.isDown) return;
621	      const delta = scroll.startY - ptr.y;
622	      if (Math.abs(delta) > 6) scroll.hasDragged = true;
623	      scroll.y = Math.max(0, Math.min(maxScroll, scroll.startScrollY + delta));
624	      cardContainer.y = -scroll.y;
625	    };
626	    const onUp = () => {
627	      scroll.active = false;
628	      scroll.hasDragged = false;
629	    };
630	
631	    this.input.on('pointerdown', onDown);
632	    this.input.on('pointermove', onMove);
633	    this.input.on('pointerup', onUp);
634	
635	    this.overlayCleanup = () => {
636	      this.input.off('pointerdown', onDown);
637	      this.input.off('pointermove', onMove);
638	      this.input.off('pointerup', onUp);
639	    };
640	  }
641	
642	  /** 캐릭터 선택 오버레이 숨김 */
643	  private hideCharSelectOverlay() {
644	    this.overlayCleanup?.();
645	    this.overlayCleanup = undefined;
646	    this.charOverlayObjects.forEach(o => o.destroy());
647	    this.charOverlayObjects = [];
648	    this.updateCharFilterRow();
649	  }
650	
651	  /** 이번 달 말일까지 남은 일수 */
652	  private calcDaysUntilMonthEnd(): number {
653	    const now = new Date();
654	    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
655	    const diff = lastDay.getTime() - now.getTime();
656	    return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
657	  }
658	
659	  /** 보상수령 버튼 상태 갱신 */
660	  private updateRewardUI() {
661	    if (!this.rewardBtnBg || !this.rewardBtnLabel) return;
662	
663	    const btn = this.rewardBtnBg;
664	    const label = this.rewardBtnLabel;
665	
666	    const reward = this.prevSeasonReward;
667	
668	    // 캐릭터 필터 활성: 캐릭터별 보상 UI
669	    if (this.selectedCharFilter !== null) {
670	      btn.removeAllListeners();
671	      btn.disableInteractive();
672	
673	      if (!reward || reward.rank === null || reward.skorAwarded === 0) {
674	        btn.setFillStyle(0x555555).setStrokeStyle(3, 0x333333);
675	        label.setText('보상없음').setColor('#999999');
676	      } else if (reward.alreadyClaimed) {
677	        btn.setFillStyle(0x336633).setStrokeStyle(3, 0x224422);
678	        label.setText('수령완료').setColor('#88ff88');
679	      } else {
680	        btn.setFillStyle(0xffcc00).setStrokeStyle(3, 0xaa8800);
681	        label.setText('캐릭터 보상').setColor('#000000');
682	        btn.setInteractive({ useHandCursor: true });
683	        btn.on('pointerover', () => btn.setFillStyle(0xffe566));
684	        btn.on('pointerout', () => btn.setFillStyle(0xffcc00));
685	        btn.on('pointerdown', () => this.handleClaimCharReward());
686	      }
687	      return;
688	    }
689	
690	    btn.removeAllListeners();
691	    btn.disableInteractive();
692	
693	    if (!reward || reward.rank === null || reward.skorAwarded === 0) {
694	      // 비활성: 기록 없음 또는 100위 밖
695	      btn.setFillStyle(0x555555).setStrokeStyle(3, 0x333333);
696	      label.setText('보상수령').setColor('#999999');
697	
698	    } else if (reward.alreadyClaimed) {
699	      // 비활성: 수령 완료 (초록)
700	      btn.setFillStyle(0x336633).setStrokeStyle(3, 0x224422);
701	      label.setText('수령완료').setColor('#88ff88');
702	
703	    } else {
704	      // 활성: 수령 가능 (노란색)
705	      btn.setFillStyle(0xffcc00).setStrokeStyle(3, 0xaa8800);
706	      label.setText('보상수령').setColor('#000000');
707	      btn.setInteractive({ useHandCursor: true });
708	      btn.on('pointerover', () => btn.setFillStyle(0xffe566));
709	      btn.on('pointerout', () => btn.setFillStyle(0xffcc00));
710	      btn.on('pointerdown', () => this.handleClaimReward());
711	    }
712	  }
713	
714	  /** 보상받기 버튼 클릭 처리 */
715	  private async handleClaimReward() {
716	    if (!this.rewardBtnBg || !this.rewardBtnLabel) return;
717	
718	    // 처리 중 표시 (중복 클릭 방지)
719	    this.rewardBtnBg.disableInteractive();
720	    this.rewardBtnLabel.setText('처리중...').setColor('#aaaaaa');
721	
722	    try {
723	      const result = await claimSeasonReward(this.selectedDifficulty);
724	
725	      if (result.success && (result.skorAwarded ?? 0) > 0) {
726	        if (this.prevSeasonReward) {
727	          this.prevSeasonReward = { ...this.prevSeasonReward, alreadyClaimed: true };
728	        }
729	        this.updateRewardUI();
730	
731	        // 획득 플래시 연출
732	        const flashText = this.add.text(
733	          this.scale.width / 2, this.scale.height / 2 - 60,
734	          `+${result.skorAwarded} SKOR 획득!`, {
735	            fontSize: '24px',
736	            color: '#ffcc00',
737	            fontStyle: 'bold',
738	            stroke: '#000',
739	            strokeThickness: 5,
740	          }
741	        ).setOrigin(0.5);
742	
743	        this.tweens.add({
744	          targets: flashText,
745	          alpha: { from: 1, to: 0 },
746	          y: flashText.y - 40,
747	          duration: 1500,
748	          ease: 'Cubic.easeOut',
749	          onComplete: () => flashText.destroy(),
750	        });
751	      } else {
752	        if (this.prevSeasonReward && result.alreadyClaimed) {
753	          this.prevSeasonReward = { ...this.prevSeasonReward, alreadyClaimed: true };
754	        }
755	        this.updateRewardUI();
756	      }
757	    } catch {
758	      // 실패 시 원래 상태로 복구
759	      this.updateRewardUI();
