771	      const result = await claimCharacterReward(this.selectedCharFilter);
772	
773	      if (result.success && (result.skorAwarded ?? 0) > 0) {
774	        if (this.prevSeasonReward) {
775	          this.prevSeasonReward = { ...this.prevSeasonReward, alreadyClaimed: true };
776	        }
